package com.berling.marketplace.utils\n\n/**\n * MessageValidator handles validation of messages to prevent link and phone number sharing\n * Implements warning system and autoban for repeated violations\n */\nobject MessageValidator {\n\n    private val LINK_PATTERNS = listOf(\n        Regex(\"https?://\"),\n        Regex(\"www\\\\.\"),\n        Regex(\"ftp://\"),\n        Regex(\"@[a-zA-Z0-9.-]+\\\\.[a-zA-Z]{2,}\"), // Email-like patterns\n        Regex(\"\\\\b[a-zA-Z0-9.-]+\\\\.[a-zA-Z]{2,}\\\\b\") // Domain patterns\n    )\n\n    private val PHONE_PATTERNS = listOf(\n        Regex(\"\\\\+?\\\\d{1,3}[-.]?\\\\(?\\\\d{1,4}\\\\)?[-.]?\\\\d{1,4}[-.]?\\\\d{1,9}\"),\n        Regex(\"\\\\(?\\\\d{3}\\\\)?[-.]?\\\\d{3}[-.]?\\\\d{4}\"),\n        Regex(\"\\\\b\\\\d{10,}\\\\b\"),\n        Regex(\"\\\\+\\\\d{1,3}\\\\s?\\\\d{1,14}\")\n    )\n\n    /**\n     * Validate message for links and phone numbers\n     */\n    fun validateMessage(message: String): MessageValidationResult {\n        val detectedLinks = detectLinks(message)\n        val detectedPhones = detectPhoneNumbers(message)\n\n        return when {\n            detectedLinks.isNotEmpty() && detectedPhones.isNotEmpty() -> {\n                MessageValidationResult(\n                    isValid = false,\n                    hasLinks = true,\n                    hasPhoneNumbers = true,\n                    detectedItems = detectedLinks + detectedPhones,\n                    rejectionReason = \"link_and_phone_detected\",\n                    rejectionMessage = \"Messages cannot contain links or phone numbers. Please use the platform's messaging features instead.\"\n                )\n            }\n            detectedLinks.isNotEmpty() -> {\n                MessageValidationResult(\n                    isValid = false,\n                    hasLinks = true,\n                    hasPhoneNumbers = false,\n                    detectedItems = detectedLinks,\n                    rejectionReason = \"link_detected\",\n                    rejectionMessage = \"Messages cannot contain links. Please use the platform's messaging features instead.\"\n                )\n            }\n            detectedPhones.isNotEmpty() -> {\n                MessageValidationResult(\n                    isValid = false,\n                    hasLinks = false,\n                    hasPhoneNumbers = true,\n                    detectedItems = detectedPhones,\n                    rejectionReason = \"phone_number_detected\",\n                    rejectionMessage = \"Messages cannot contain phone numbers. Please use the platform's messaging features instead.\"\n                )\n            }\n            else -> {\n                MessageValidationResult(\n                    isValid = true,\n                    hasLinks = false,\n                    hasPhoneNumbers = false,\n                    detectedItems = emptyList(),\n                    rejectionReason = null,\n                    rejectionMessage = null\n                )\n            }\n        }\n    }\n\n    /**\n     * Detect links in message\n     */\n    private fun detectLinks(message: String): List<String> {\n        val detectedLinks = mutableListOf<String>()\n        \n        for (pattern in LINK_PATTERNS) {\n            val matches = pattern.findAll(message)\n            for (match in matches) {\n                detectedLinks.add(match.value)\n            }\n        }\n        \n        return detectedLinks.distinct()\n    }\n\n    /**\n     * Detect phone numbers in message\n     */\n    private fun detectPhoneNumbers(message: String): List<String> {\n        val detectedPhones = mutableListOf<String>()\n        \n        for (pattern in PHONE_PATTERNS) {\n            val matches = pattern.findAll(message)\n            for (match in matches) {\n                // Validate it's actually a phone number and not just a number\n                val value = match.value\n                if (isLikelyPhoneNumber(value)) {\n                    detectedPhones.add(value)\n                }\n            }\n        }\n        \n        return detectedPhones.distinct()\n    }\n\n    /**\n     * Check if a string is likely a phone number\n     */\n    private fun isLikelyPhoneNumber(value: String): Boolean {\n        val digitsOnly = value.replace(Regex(\"[^0-9]\"), \"\")\n        return digitsOnly.length >= 7 && digitsOnly.length <= 15\n    }\n\n    /**\n     * Get warning message for user\n     */\n    fun getWarningMessage(violationCount: Int): String {\n        return when (violationCount) {\n            1 -> \"⚠️ Warning: This is your first violation. Sharing links or phone numbers is not allowed. Repeated violations will result in account suspension.\"\n            2 -> \"⚠️ Final Warning: This is your second violation. One more violation will result in a 7-day account ban.\"\n            else -> \"❌ Your account has been suspended for 7 days due to repeated violations.\"\n        }\n    }\n\n    /**\n     * Check if message contains suspicious patterns\n     */\n    fun containsSuspiciousPatterns(message: String): Boolean {\n        val suspiciousPatterns = listOf(\n            Regex(\"(?i)click here\"),\n            Regex(\"(?i)download now\"),\n            Regex(\"(?i)limited time\"),\n            Regex(\"(?i)act now\"),\n            Regex(\"(?i)urgent\"),\n            Regex(\"(?i)verify account\")\n        )\n        \n        return suspiciousPatterns.any { it.containsMatchIn(message) }\n    }\n\n    /**\n     * Sanitize message by removing suspicious content\n     */\n    fun sanitizeMessage(message: String): String {\n        var sanitized = message\n        \n        // Remove links\n        for (pattern in LINK_PATTERNS) {\n            sanitized = pattern.replace(sanitized, \"[link removed]\")\n        }\n        \n        // Remove phone numbers\n        for (pattern in PHONE_PATTERNS) {\n            sanitized = pattern.replace(sanitized, \"[phone removed]\")\n        }\n        \n        return sanitized\n    }\n}\n\ndata class MessageValidationResult(\n    val isValid: Boolean,\n    val hasLinks: Boolean = false,\n    val hasPhoneNumbers: Boolean = false,\n    val detectedItems: List<String> = emptyList(),\n    val rejectionReason: String? = null,\n    val rejectionMessage: String? = null\n)\n
